'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { installMediaGain, mediaAction } = require('../src/main/media-gain.cjs');
const output = `'use strict';
// Generated by scripts/build-media-preload.cjs from media-gain.cjs. No page IPC bridge.
const { ipcRenderer, webFrame } = require('electron');
const installMediaGain = ${installMediaGain.toString()};
const mediaAction = ${mediaAction.toString()};
if (/^(?:https?:|about:blank$|about:srcdoc$)/.test(location.href)) {
  let initial;
  try { const nonce = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : String(performance.timeOrigin) + ':' + Math.random().toString(36).slice(2); initial = ipcRenderer.sendSync('aster:media:document-start', { url: location.href, nonce }); } catch {}
  if (initial?.key && Number.isFinite(initial.volume)) {
    // webFrame executes in this exact document before its first inline script,
    // including under strict page CSP. Use only owned source and JSON values.
    webFrame.executeJavaScript('(' + installMediaGain.toString() + ')(' + JSON.stringify(initial.key) + ',' + JSON.stringify(initial.volume) + ')').then(() => ipcRenderer.send('aster:media:preload-installed', {url:location.href,key:initial.key})).catch(error => ipcRenderer.send('aster:media:preload-failure', {url:location.href,key:initial.key,error:String(error?.message||error).slice(0,1000)}));
    ipcRenderer.on('aster:media:volume', (_event, message) => {
      if (!message || message.key !== initial.key || message.url !== location.href || !Number.isFinite(message.volume) || message.volume < 0 || message.volume > 1) return;
      webFrame.executeJavaScript('(' + mediaAction.toString() + ')(' + JSON.stringify(initial.key) + ',"volume",' + JSON.stringify(message.volume) + ')').catch(() => {});
    });
    let pending;
    const changed = () => { clearTimeout(pending); pending = setTimeout(() => { pending = null; ipcRenderer.send('aster:media:changed', { url: location.href, key: initial.key }); }, 80); };
    for (const name of ['play', 'pause', 'ended', 'loadedmetadata', 'emptied', 'enterpictureinpicture', 'leavepictureinpicture']) addEventListener(name, changed, true);
    addEventListener('DOMContentLoaded', changed, { once: true });
    addEventListener('unload', () => clearTimeout(pending), { once: true });
  }
}
`;
fs.writeFileSync(path.join(__dirname, '../src/main/media-preload.cjs'), output);
console.log('Generated sandboxed media preload');
